            data.Note = RevDataFieldParser.ToStr(cells[2]);            // 含义、单位与取值说明（给策划看，程序不读取）

            return true;
        }
    }

    /// <summary>PieceConfig 表的容器（主键：Kind，10 个字段，9 条数据）</summary>
    public sealed class PieceConfigTable : RevDataTable<string, PieceConfig>
    {
        /// <summary>便捷访问；未加载时为 null（先 RevDataTableManager.LoadAsync&lt;PieceConfigTable&gt;()）</summary>
        public static PieceConfigTable Instance => RevDataTableManager.Get<PieceConfigTable>();

        /// <summary>表名 = PieceConfig；数据文件默认取逻辑路径 "Data/PieceConfig"</summary>
        public PieceConfigTable() : base("PieceConfig") { }

        /// <summary>主键取值</summary>
        protected override string GetKey(in PieceConfig data) => data.Kind;

        /// <summary>一行文本 → 一条数据（生成代码，零反射、零装箱）</summary>
        protected override bool ParseRow(string[] cells, out PieceConfig data)
        {
            data = default;

            // 列数比结构少 → 数据文件与结构不匹配，按坏行处理
            if (cells.Length < 10) return false;

            data.Kind = RevDataFieldParser.ToStr(cells[0]);            // 棋子外形编号，必须与代码枚举 PieceKind 同名；请勿改名、不要增删行（新增外形需程序先加枚举和立绘）
            data.DisplayName = RevDataFieldParser.ToStr(cells[1]);     // 中文名，显示在手牌、血条和日志里；星级后缀（如“1★”）由程序拼接
            data.Class = RevDataFieldParser.ToStr(cells[2]);           // 职业，只能填 Guard / Mage / Ranger / Assassin；同职业在场凑够 3 个、5 个触发职业加成
            data.SpriteKey = RevDataFieldParser.ToStr(cells[3]);       // 立绘文件名里的棋子名（ArtRes 中“棋子_<本列><星级>_立绘”），与美术资源一一对应，改名需同步改资源
            data.Hp = RevDataFieldParser.ToInt(cells[4]);              // 1★ 基础最大生命；2★、3★ 按星级表倍率放大后向下取整
            data.Attack = RevDataFieldParser.ToInt(cells[5]);          // 1★ 基础攻击力；2★、3★ 按星级表倍率放大后向下取整
            data.MovePattern = RevDataFieldParser.ToStr(cells[6]);     // 走法，只能填 Step（单步）/ Slide（滑步）/ Knight（马步）/ Cannon（炮，隔一子打）
            data.MoveRange = RevDataFieldParser.ToInt(cells[7]);       // 走几步：Step、Knight 使用；Slide、Cannon 填 0 表示不限距离
            data.IsRanged = RevDataFieldParser.ToBool(cells[8]);       // 是否远程（TRUE/FALSE）：我方远程全盘弹幕；敌方普通远程两格直线，炮隔子；近战相邻一格
            data.UnlockedAtStart = RevDataFieldParser.ToBool(cells[9]); // 开局是否已在手牌池（TRUE/FALSE）；其余棋子靠章节奖励“新棋子”解锁

            return true;
        }
    }

    /// <summary>StarConfig 表的容器（主键：Star，4 个字段，3 条数据）</summary>
    public sealed class StarConfigTable : RevDataTable<int, StarConfig>
    {
        /// <summary>便捷访问；未加载时为 null（先 RevDataTableManager.LoadAsync&lt;StarConfigTable&gt;()）</summary>
        public static StarConfigTable Instance => RevDataTableManager.Get<StarConfigTable>();

        /// <summary>表名 = StarConfig；数据文件默认取逻辑路径 "Data/StarConfig"</summary>
        public StarConfigTable() : base("StarConfig") { }

        /// <summary>主键取值</summary>
        protected override int GetKey(in StarConfig data) => data.Star;

        /// <summary>一行文本 → 一条数据（生成代码，零反射、零装箱）</summary>
        protected override bool ParseRow(string[] cells, out StarConfig data)
        {
            data = default;

            // 列数比结构少 → 数据文件与结构不匹配，按坏行处理
            if (cells.Length < 4) return false;

            data.Star = RevDataFieldParser.ToInt(cells[0]);            // 星级（1~3），三行必须齐全
            data.HpScale = RevDataFieldParser.ToFloat(cells[1]);       // 相对 1★ 的最大生命倍率
            data.AttackScale = RevDataFieldParser.ToFloat(cells[2]);   // 相对 1★ 的攻击力倍率
            data.PlayerBodySize = RevDataFieldParser.ToInt(cells[3]);  // 我方该星级棋子占的格子边长（1=1×1，2=2×2）；敌方普通棋固定 1×1，Boss 占格见章节表

            return true;
        }
    }
}
